const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',policy:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',contracts:'<path d="M6 3h9l4 4v14H6z"/><path d="M14 3v5h5M9 12h7M9 16h5"/>',integration:'<path d="M7 3v5m10-5v5M5 8h14v4a7 7 0 0 1-14 0zM12 19v3"/>',fleet:'<rect x="3" y="4" width="18" height="6" rx="2"/><rect x="3" y="14" width="18" height="6" rx="2"/><path d="M7 7h.01M7 17h.01M12 7h5M12 17h5"/>',observe:'<path d="M2 12h4l3-8 5 16 3-8h5"/>',rollout:'<path d="M4 19V5m0 7h8m0 0-3-3m3 3-3 3M16 4h4v16h-4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',warn:'<path d="M12 3 2 21h20zM12 9v5m0 3v.1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',note:'<path d="M4 3h16v14l-5 4H4zM8 8h8M8 12h6"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.overview}</svg>`}
const concepts={console:{n:'01',title:'Operations console',short:'Console',class:'console',tag:'Fleet first',description:'A precise, information-dense console for the people keeping policy enforcement healthy.',best:'Daily operations and incident triage',tradeoff:'More information to scan; less room for long policy explanations.',tags:['Persistent navigation','Fast triage','Dense tables'],color:'#284653'},workspace:{n:'02',title:'Policy workspace',short:'Workspace',class:'workspace',tag:'Knowledge first',description:'A calm editorial workspace that puts policy meaning, source authority, and evidence together.',best:'Policy authors and integration reviewers',tradeoff:'Fleet problems are one level deeper than in an operations console.',tags:['Master–detail','Source context','Readable policy'],color:'#717a55'},atlas:{n:'03',title:'Service atlas',short:'Atlas',class:'atlas',tag:'Relationships first',description:'A spatial view of sources, policy records, and enforcement endpoints, built for investigation.',best:'Understanding impact and tracing delivery',tradeoff:'Maps need careful grouping as the number of services grows.',tags:['Topology navigation','Live inspector','Impact paths'],color:'#31566a'},guided:{n:'04',title:'Guided operations',short:'Guided',class:'guided',tag:'Next action first',description:'A task-oriented experience that helps operators inspect, validate, assign, and confirm safely.',best:'Occasional operators and controlled changes',tradeoff:'A guided sequence adds steps for experienced users.',tags:['Action queue','Explicit stages','Bounded decisions'],color:'#668d67'}};
const screens=[['overview','Overview','overview'],['policies','Policies','policy'],['contracts','External policies','contracts'],['integrations','Integrations','integration'],['fleet','Endpoints','fleet'],['map','Service map','fleet'],['observability','Observability','observe'],['rollouts','Rollouts','rollout']];
let selectedRecord='approval',detailTab='definition',filter='',query='',current={concept:null,screen:'overview'},dialogOpener=null;
const initialPolicies=[{id:'approval',name:'Change approval guard',rev:'r17',origin:'Authored',status:'Active',scope:'Production changes',coverage:'2 / 3 endpoints',rule:'Require <em>two distinct maintainer approvals</em> before a production change.',owner:'Platform team'},{id:'access',name:'Privileged access window',rev:'r8',origin:'Authored',status:'Active',scope:'Privileged access',coverage:'3 / 3 endpoints',rule:'Permit elevated access only during an <em>approved, unexpired access window</em>.',owner:'Security team'},{id:'window',name:'Production change window',rev:'r11',origin:'Authored',status:'Draft',scope:'Production changes',coverage:'Not assigned',rule:'Allow changes during <em>published maintenance windows</em>.',owner:'Platform team'},{id:'remediation',name:'Verified remediation',rev:'r6',origin:'Translated',status:'Active',scope:'Remediation workflow',coverage:'2 / 2 endpoints',rule:'Require <em>fresh verification evidence</em> before recording remediation as complete.',owner:'Security team'},{id:'build',name:'Build provenance',rev:'r12',origin:'Authored',status:'Active',scope:'Release pipeline',coverage:'3 / 3 endpoints',rule:'Require a build from the <em>reviewed commit and an approved runner</em>.',owner:'Platform team'},{id:'bypass',name:'Emergency bypass',rev:'r3',origin:'Authored',status:'Paused',scope:'Emergency operations',coverage:'Not assigned',rule:'Allow a <em>time-limited, audited exception</em> for an authorized incident commander.',owner:'Security team'}];
let policies=structuredClone(initialPolicies),observed=false,assigned=false,scenario='valid';
const contractRows=[{id:'closure',name:'Change closure prerequisites',source:'ServiceNow',state:'Partial coverage',age:'6 min ago',version:'source-81',summary:'Two approvals, supporting evidence, and an external scripted condition.'},{id:'branch',name:'Protected branch rules',source:'GitHub',state:'Current',age:'1 min ago',version:'source-23',summary:'Required reviews and status checks for the protected branch.'},{id:'maintenance',name:'Maintenance window constraints',source:'ServiceNow',state:'Stale',age:'38 min ago',version:'source-17',summary:'Permitted change windows for the selected service.'}];
const endpoints=[{id:'east-01',kind:'Enforcement',site:'US East',state:'Connected',desired:'r17',active:'r17',local:'8',telemetry:'Compliant'},{id:'east-02',kind:'Enforcement',site:'US East',state:'Connected',desired:'r17',active:'r17',local:'12',telemetry:'Compliant'},{id:'east-03',kind:'Enforcement',site:'US East',state:'Disconnected',desired:'r17',active:'r16',local:'7',telemetry:'Missing canary'},{id:'integration-01',kind:'Integration',site:'US East',state:'Connected',desired:'install-9',active:'install-9',local:'—',telemetry:'Compliant'}];
function readReviews(){try{return JSON.parse(localStorage.getItem('ipe-design-review')||'{}')}catch{return {}}}
let reviews=readReviews();
function persist(){try{localStorage.setItem('ipe-design-review',JSON.stringify(reviews))}catch{toast('Browser storage is unavailable. Export your review to keep it.')}}
function badge(label,tone){tone=tone||(/Active|Current|Connected|Compliant|Allow|Applied|Complete/.test(label)?'good':/Partial|Waiting|Draft|Review|Pending/.test(label)?'warn':/Stale|Disconnected|Missing|Denied|Blocked/.test(label)?'bad':/Translated|External/.test(label)?'purple':'blue');return `<span class="badge ${tone}"><span class="dot"></span>${esc(label)}</span>`}
function btn(label,action,cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`}
function href(screen,concept=current.concept){return `#${concept}/${screen}`}
function link(label,screen,cls=''){return `<a class="btn ${cls}" href="${href(screen)}">${label}</a>`}
function brand(){return '<div class="brand"><span class="brandmark">//</span> ipe<span style="font-size:10px;letter-spacing:1px;font-weight:400;opacity:.55;margin-left:4px">ADMIN</span></div>'}
function spark(color='#7c9eac'){return `<svg class="spark" viewBox="0 0 300 60" preserveAspectRatio="none" aria-label="Illustrative latency trend"><path d="M0 42 15 40 25 43 35 32 46 35 58 31 70 34 84 24 95 28 108 21 120 27 131 20 143 22 155 15 167 20 178 13 191 17 203 10 216 15 228 8 242 13 257 6 271 11 287 8 300 5" fill="none" stroke="${color}" stroke-width="2"/><path d="M0 42 15 40 25 43 35 32 46 35 58 31 70 34 84 24 95 28 108 21 120 27 131 20 143 22 155 15 167 20 178 13 191 17 203 10 216 15 228 8 242 13 257 6 271 11 287 8 300 5V60H0Z" fill="${color}" opacity=".09"/></svg>`}
function stat(label,value,note,i){return `<div class="stat"><span class="stat-icon">${icon(i||'overview')}</span><label>${label}</label><strong>${value}</strong><small>${note}</small></div>`}
function panel(title,body,right='',sub=''){return `<section class="panel"><header class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</header>${body}</section>`}
function head(title,subtitle,action='',eyebrow=''){return `<header class="page-head"><div>${eyebrow?`<div class="kicker">${eyebrow}</div>`:''}<h1>${title}</h1><p>${subtitle}</p></div>${action}</header>`}
function foot(){return `<footer class="review-foot"><span>Illustrative prototype · Northstar / Production · No live connections</span><button data-action="reset">Reset this demo</button><button data-action="feedback">What would you refine?</button></footer>`}
function toolbar(placeholder,options=[]){return `<div class="toolbar"><label class="search">${icon('search')}<input id="record-search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(query)}"></label>${options.length?`<select id="record-filter" aria-label="Filter records" class="filter"><option value="">All ${current.screen==='policies'?'states':'types'}</option>${options.map(o=>`<option ${filter===o?'selected':''}>${o}</option>`).join('')}</select>`:''}<span class="grow"></span><span class="mono muted">PRODUCTION</span></div>`}
function policyTable(limit){const rows=policies.filter(p=>(!filter||p.status===filter)&&(!query||`${p.name} ${p.origin}`.toLowerCase().includes(query.toLowerCase()))).slice(0,limit||99);return `<div class="table-wrap"><table><thead><tr><th>Executable policy</th><th>Origin</th><th>Revision</th><th>State</th><th>Applied</th></tr></thead><tbody>${rows.map(p=>`<tr class="clickable-row"><td><button class="record-link" data-action="policy" data-id="${p.id}">${esc(p.name)}</button><span class="sub">${p.scope}</span></td><td>${badge(p.origin,p.origin==='Translated'?'purple':'blue')}</td><td class="mono">${p.rev}</td><td>${badge(p.status)}</td><td>${p.id==='approval'&&assigned?'3 / 3 endpoints':p.coverage}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No policies match this filter.</div>':''}</div>`}
function contractTable(){const rows=contractRows.filter(c=>(!filter||c.source===filter)&&(!query||c.name.toLowerCase().includes(query.toLowerCase())));return `<div class="table-wrap"><table><thead><tr><th>External policy</th><th>External enforcer</th><th>Coverage / validity</th><th>Observed</th></tr></thead><tbody>${rows.map(c=>`<tr class="clickable-row"><td><button class="record-link" data-action="contract" data-id="${c.id}">${c.name}</button><span class="sub">${c.version} · Discovered external policy</span></td><td>${c.source}</td><td>${badge(c.state)}</td><td class="mono">${c.id==='closure'&&observed?'Just now':c.age}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No external policies match this filter.</div>':''}</div>`}
function fleetTable(){const rows=endpoints.filter(e=>(!filter||e.kind===filter)&&(!query||e.id.includes(query.toLowerCase())));return `<div class="table-wrap"><table><thead><tr><th>Endpoint</th><th>Connection</th><th>Desired → active</th><th>Telemetry</th><th>Last report</th></tr></thead><tbody>${rows.map(e=>`<tr class="clickable-row"><td><button class="record-link" data-action="endpoint" data-id="${e.id}">${e.id}</button><span class="sub">${e.kind} · ${e.site}</span></td><td>${badge(e.id==='east-03'&&assigned?'Connected':e.state)}</td><td class="mono">${e.desired} → ${e.id==='east-03'&&assigned?'r17':e.active}</td><td>${badge(e.id==='east-03'&&assigned?'Compliant':e.telemetry)}</td><td class="mono">${e.id==='east-03'&&!assigned?'12 min ago':'18 sec ago'}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No endpoints match this filter.</div>':''}</div>`}
function feed(){return ['<strong>Policy r17 applied on east-02</strong><p>Central r17 mapped to local revision 12</p>','<strong>External observation published</strong><p>ServiceNow · source-81 · partial coverage</p>','<strong>Telemetry canary missing</strong><p>east-03 · last confirmed 12 minutes ago</p>','<strong>GitHub facts synchronized</strong><p>Snapshot 204 · original validity preserved</p>'].map((t,i)=>`<div class="feed-item"><span class="feed-bullet">${icon(['check','contracts','warn','refresh'][i])}</span><div>${t}</div><time>${['1m','6m','12m','14m'][i]}</time></div>`).join('')}
function health(){return `<div class="panel-body"><div class="health-row">${icon('fleet')}Execution health ${badge(assigned?'4 / 4 connected':'3 / 4 connected',assigned?'good':'warn')}</div><div class="health-row">${icon('contracts')}External evidence ${badge('1 stale observation','warn')}</div><div class="health-row">${icon('rollout')}Assignment delivery ${badge(assigned?'All applied':'1 waiting',assigned?'good':'warn')}</div><div class="health-row">${icon('observe')}Telemetry compliance ${badge(assigned?'Compliant':'1 missing canary',assigned?'good':'bad')}</div></div>`}
function tasks(){return `<div class="task-card"><span class="task-icon">${icon('rollout')}</span><div><h3>${assigned?'Approval guard applied everywhere':'Confirm approval guard rollout'}</h3><p>${assigned?'All three enforcement endpoints report r17.':'east-03 has not reported revision r17.'}</p></div>${link('Review '+icon('arrow'),'rollouts','small')}</div><div class="task-card"><span class="task-icon">${icon('contracts')}</span><div><h3>Review external coverage gap</h3><p>ServiceNow returned a scripted condition we cannot interpret.</p></div>${btn('Inspect '+icon('arrow'),'contract','small','data-id="closure"')}</div><div class="task-card"><span class="task-icon">${icon('observe')}</span><div><h3>Investigate telemetry freshness</h3><p>Keep observability compliance separate from runtime health.</p></div>${link('Investigate '+icon('arrow'),'observability','small')}</div>`}
function overviewConsole(){return `${head('Operations overview','A clear view of what is running, what is current, and what needs attention.',link('Review rollout '+icon('arrow'),'rollouts','primary'))}<div class="stats">${stat('Enforcement endpoints',assigned?'3 / 3':'2 / 3',assigned?'All reporting current assignments':'1 endpoint awaiting reconnection','fleet')}${stat('Executable policies',policies.length,'4 active · 1 draft · 1 paused','policy')}${stat('External policies','3','2 sources · 1 coverage gap','contracts')}${stat('Telemetry compliance',assigned?'100%':'75%',assigned?'All required checks received':'3 of 4 endpoints compliant','observe')}</div>${!assigned?`<div class="notice">${icon('warn')}<span><b>east-03 is behind.</b> Active r16 · desired r17 · last report 12 minutes ago.</span>${link('Inspect endpoint','fleet','small quiet')}</div>`:''}<div class="two-col"><div class="stack">${panel('Needs attention',tasks(),'<span class="mono muted">3 ITEMS</span>')}${panel('Executable policies',policyTable(3),link('View all','policies','small quiet'))}</div><div class="stack">${panel('Independent health signals',health())}${panel('Recent activity',feed())}</div></div>`}
function workspaceOverview(){return `${head('Policy, with context.','Understand what IPE enforces, what external systems require, and where the evidence is incomplete.',link('Open policy library '+icon('arrow'),'policies','primary'),'THE POLICY WORKSPACE')}<div class="document-note">A local decision is only as useful as the policy and evidence behind it.</div><div class="stats">${stat('Executable rules',policies.length,'Authored and explicitly translated')}${stat('External policies','3','Observed knowledge, source enforced')}${stat('Review queue','2','A coverage gap and a draft')}</div><div class="two-col"><div class="stack">${panel('Continue reviewing',`<div class="panel-body"><div class="row spread">${badge('Executable policy','blue')}<span class="mono muted">r17</span></div><div class="paper-preview"><small class="kicker muted">PRODUCTION CHANGE</small><h3>Change approval guard</h3><p>Require two distinct maintainer approvals before a production change. Evidence must refer to the exact change being evaluated.</p><div class="related-links">${btn('Read policy '+icon('arrow'),'policy','primary','data-id="approval"')}${link('See source context','contracts')}</div></div></div>`)}${panel('Source knowledge to review',contractTable())}</div><div class="stack">${panel('Your review queue',`<div class="panel-body"><div class="kind-key">EXTERNAL CONTRACT</div><h3 style="font-size:14px;margin-bottom:9px">An unmodeled condition</h3><p class="muted" style="font-size:12px;line-height:1.8">ServiceNow exposes a scripted closure condition. It remains visible as an unknown requirement.</p><div style="margin-top:18px">${btn('Inspect observation','contract','small','data-id="closure"')}</div></div>`)}<div class="callout"><strong>One catalog. Different authority.</strong>Publishing an external description updates shared knowledge. It never activates an executable policy.</div>${panel('Recent revisions',feed().split('<div class="feed-item">').slice(0,3).join('<div class="feed-item">'))}</div></div>`}
function topology(){return `<div class="topology"><svg viewBox="0 0 760 410" role="img" aria-labelledby="maptitle"><title id="maptitle">Integration publishes external policy observations to a typed catalog; enforcement pulls executable assignments.</title><defs><marker id="maparrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#5b8493"/></marker></defs><g stroke="#38586a" fill="none" stroke-width="1.5" marker-end="url(#maparrow)"><path d="M175 102H245V158H290"/><path d="M175 280H245V220H290"/><path d="M470 165H530V96H582"/><path d="M470 192H582"/><path d="M470 220H530V291H582"/></g><g fill="#7796a7" font-size="9"><text x="196" y="89">observe</text><text x="202" y="305">observe via integration</text><text x="487" y="143">assigned policies</text><text x="485" y="323">periodic pull</text></g>${mapNode(30,65,145,76,'ServiceNow','External constraints','integration','servicenow','#6fac9b')}${mapNode(30,245,145,76,'GitHub','Branch constraints','integration','github','#8897ba')}${mapNode(290,140,180,105,'Policy service','3 record families','catalog','','#7ec2b9')}${mapNode(582,60,145,72,'east-01','r17 · applied','endpoint','east-01','#70bfa7')}${mapNode(582,156,145,72,'east-02','r17 · applied','endpoint','east-02','#70bfa7')}${mapNode(582,253,145,79,'east-03',assigned?'r17 · applied':'r16 → r17 · waiting','endpoint','east-03',assigned?'#70bfa7':'#d2ad70')}<g fill="#7791a3" font-size="9" letter-spacing="1.6"><text x="31" y="35">SOURCE SYSTEMS</text><text x="290" y="118">CENTRAL CATALOG</text><text x="581" y="35">ENFORCEMENT</text></g><text x="30" y="385" fill="#6d8798" font-size="10">Select a source, catalog, or endpoint to inspect its role.</text></svg></div><div class="map-caption"><span><i class="dot" style="color:#7dc2a5"></i>Current</span><span><i class="dot" style="color:#d4b577"></i>Needs attention</span><span>Logical relationships · integration mediates source observations · fact delivery omitted</span></div>`}
function mapNode(x,y,w,h,title,sub,act,id,color){return `<g tabindex="0" role="button" aria-label="Inspect ${title}" data-action="${act}" data-id="${id}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#192c3b" stroke="${color}" stroke-opacity=".65"/><circle cx="${x+17}" cy="${y+24}" r="3" fill="${color}"/><text x="${x+29}" y="${y+28}" fill="#d3e3ec" font-size="12">${title}</text><text x="${x+17}" y="${y+50}" fill="#87a2b4" font-size="9">${sub}</text>${h>90?`<text x="${x+17}" y="${y+76}" fill="#668c9d" font-size="9">Executable · external · receipt</text>`:''}</g>`}
function atlasOverview(){return `${head('Production service map','Follow the path from an external observation to a local enforcement decision.',btn(icon('eye')+' Inspect selected','endpoint','','data-id="east-03"'),'NORTHSTAR / US EAST')}<div class="atlas-layout"><div class="panel">${topology()}</div><aside class="panel node-inspector"><div class="kicker muted">SELECTED ENDPOINT</div><h2>east-03</h2>${badge(assigned?'Connected':'Disconnected')}<div class="field-grid"><div><small>Desired policy</small><p>Change approval guard <span class="mono">r17</span></p></div><div><small>Last reported active</small><p><span class="mono">${assigned?'r17 · local 8':'r16 · local 7'}</span></p></div><div><small>Telemetry compliance</small><p>${assigned?'Compliant':'Missing canary'}</p></div><div><small>Evidence freshness</small><p>Last known snapshot expired</p></div></div>${btn('Inspect endpoint '+icon('arrow'),'endpoint','primary','data-id="east-03"')}</aside></div><div class="stats">${stat('Source connections','2','ServiceNow + GitHub','integration')}${stat('Catalog families','3','Executable · contract · evaluation','contracts')}${stat('Current assignments',assigned?'3 / 3':'2 / 3','Reported, not inferred from delivery','rollout')}${stat('Trace pipeline','1.8k','Illustrative spans in the last hour','observe')}</div><div class="two-col">${panel('Changes across the map',feed())}${panel('Keep these signals separate',health(),link('Open observability','observability','small quiet'))}</div>`}
function guidedOverview(){return `${head('What needs your attention?','Three focused tasks for the production environment. Choose one to move it forward.','', 'YOUR OPERATIONS QUEUE')}<div class="guide-hero"><div><span class="kicker">RECOMMENDED NEXT TASK</span><h2>${assigned?'Your rollout is confirmed.':'Finish the approval guard rollout.'}</h2><p>${assigned?'All managed endpoints have reported the intended revision. You can now review the external coverage gap.':'Two endpoints are current. Inspect the third endpoint before confirming that this change is complete.'}</p></div>${link(assigned?'Review external knowledge '+icon('arrow'):'Continue rollout '+icon('arrow'),assigned?'contracts':'rollouts','primary')}</div><div class="guide-summary"><span><b>3</b> open tasks</span><span><b>2</b> source connections</span><span><b>${assigned?'0':'1'}</b> endpoint needs attention</span></div><div class="two-col"><div class="stack">${panel('Pick up a task',tasks())}${panel('Recently completed',`<div class="task-card"><div class="task-icon">${icon('check')}</div><div><h3>Publish the change approval policy</h3><p>Revision r17 was published by the Platform team.</p></div><span class="task-state">Complete</span></div><div class="task-card"><div class="task-icon">${icon('check')}</div><div><h3>Refresh GitHub approval facts</h3><p>Snapshot 204 retains its original observation validity.</p></div><span class="task-state">Complete</span></div>`)}</div><div class="stack">${panel('Before you take action',`<div class="panel-body"><div class="health-row">${icon('check')}Your role <strong style="margin-left:auto">Policy operator</strong></div><div class="health-row">${icon('globe')}Environment <strong style="margin-left:auto">Production</strong></div><div class="health-row">${icon('policy')}Changes <strong style="margin-left:auto">Simulated only</strong></div></div>`)}<div class="callout"><strong>Observation is not activation.</strong>Reviewing or refreshing an external policy never changes the policy running at an endpoint.</div></div></div>`}
function policyDetailsBase(p,inline=false){return `<div class="row spread">${badge('Locally enforced','blue')}<span class="mono muted">${p.rev} · ${p.origin.toLowerCase()}</span></div>${inline?`<h2>${esc(p.name)}</h2><p class="muted" style="font-size:11px">${p.scope} · owned by ${p.owner}</p>`:''}<div class="tabs"><button data-action="detailtab" data-tab="definition" class="${detailTab==='definition'?'active':''}">Rule</button><button data-action="detailtab" data-tab="deployments" class="${detailTab==='deployments'?'active':''}">Enforcement targets</button><button data-action="detailtab" data-tab="evidence" class="${detailTab==='evidence'?'active':''}">Evidence & origin</button></div>${detailTab==='definition'?`<div class="rule"><small>REQUIREMENT FOR ${applicability(p).operation.toUpperCase()}</small><p>${p.rule}</p></div><div class="field-grid"><div><small>Evaluation authority</small><p>IPE enforcement endpoint</p></div><div><small>Publication authority</small><p>${p.owner}</p></div><div><small>Origin</small><p>${p.origin==='Translated'?'Explicitly translated from source':'Locally authored'}</p></div><div><small>Current state</small><p>${badge(p.status)}</p></div></div><div class="detail-section"><h3>Try the approval guard example</h3><p class="muted">Illustrative r17 test fixture; not a general policy evaluator.</p><label class="form-label" for="scenario">Approval evidence</label><select id="scenario" class="form-input"><option value="valid" ${scenario==='valid'?'selected':''}>Two distinct maintainers · fresh evidence</option><option value="single" ${scenario==='single'?'selected':''}>One maintainer · fresh evidence</option><option value="expired" ${scenario==='expired'?'selected':''}>Two maintainers · expired evidence</option></select><div style="margin-top:12px">${btn('Simulate candidate test','test','small')}</div><div id="test-result" style="margin-top:12px"></div></div>`:detailTab==='deployments'?`<div class="callout"><strong>Published and active are different states.</strong>These are explicit endpoint reports, mapped to the central policy revision.</div><div style="margin-top:20px">${policyTargetTable(p)}</div><div class="related-links">${p.id==='approval'?link('Review assignment','rollouts','primary'):''}</div>`:`<div class="definition-row"><span>Resource kind</span><strong>Executable policy revision</strong></div><div class="definition-row"><span>Required facts</span><strong>${esc(applicability(p).requirement)}</strong></div><div class="definition-row"><span>Source dependence</span><strong>${p.sourceDependence || (p.origin==='Translated'?'Pinned external observation validity':'Independent local policy')}</strong></div><div class="definition-row"><span>Evidence use</span><strong>Fresh at evaluation time</strong></div><div class="callout"><strong>External origin does not mean external enforcement.</strong>This resource is executable in IPE. An external policy observation is a different resource.</div><div class="related-links">${link('Inspect external policies','contracts')}</div>`}`}
function policiesScreen(){const p=policies.find(p=>p.id===selectedRecord)||policies[0];let content;if(current.concept==='workspace'){content=`<div class="workbench"><div class="record-list"><div class="kicker muted" style="padding:10px">EXECUTABLE REVISIONS</div>${policies.map(p=>`<button data-action="select-record" data-id="${p.id}" class="${p.id===selectedRecord?'active':''}"><strong>${esc(p.name)}</strong><small>${p.rev} · ${p.status} · ${p.origin}</small></button>`).join('')}</div><article class="work-detail">${policyDetails(p,true)}</article></div>`}else content=panel('Executable policy library',toolbar('Search executable policies',['Active','Draft','Paused'])+policyTable(),`<span class="mono muted">${policies.length} RECORDS</span>`);return `${head(current.concept==='workspace'?'The executable library':'Executable policies','These rules are explicitly authored or translated, then assigned to IPE endpoints.',btn(icon('plus')+' New draft','new-policy','primary'),current.concept==='workspace'?'POLICY / LOCAL ENFORCEMENT':'')}${current.concept==='guided'?journey(0,['Inspect','Test','Assign','Confirm'])+stepIntro('Start with a policy revision','Inspect the rule and test a scenario before assigning it to an endpoint.'):''}${content}${current.concept!=='workspace'?`<div class="callout" style="margin-top:20px"><strong>Source observations have their own lifecycle.</strong>Looking for a rule enforced by ServiceNow or GitHub? ${link('Open external policies '+icon('arrow'),'contracts','small quiet')}</div>`:''}`}
function contractsScreen(){return `${head(current.concept==='workspace'?'What external systems require':'External policies','Discovered constraints remain source-enforced knowledge. Freshness and coverage are independent.',btn(icon('refresh')+' Observe source','observe-source','primary'),current.concept==='workspace'?'POLICY / EXTERNAL AUTHORITY':'')}${current.concept==='guided'?journey(0,['Inspect','Observe','Review gaps','Record'])+stepIntro('Understand the source requirement','A partial observation can be useful, but it cannot prove all external conditions are known.'):''}<div class="notice neutral">${icon('contracts')}<span>Publishing these observations updates knowledge. It does not activate an IPE rule.</span></div>${panel('Observed external policy definitions',toolbar('Search external policies',['ServiceNow','GitHub'])+contractTable())}<div class="two-col" style="margin-top:20px">${panel('External evaluation observations',`<div class="feed-item"><span class="feed-bullet">${icon('warn')}</span><div><strong>Change CHG-2041 · closure rejected</strong><p>ServiceNow · intended actor: change operator · observed 8 minutes ago</p></div>${btn('Inspect','receipt','small')}</div><div class="feed-item"><span class="feed-bullet">${icon('check')}</span><div><strong>Change CHG-2038 · validation accepted</strong><p>Reported result for the recorded input; not a future execution grant.</p></div>${btn('Inspect','receipt','small','data-id="accepted"')}</div>`)}<div class="callout"><strong>Keep the source’s uncertainty visible.</strong>Failed discovery is not a deleted rule. An unmodeled condition remains unknown until a supported observation resolves it.</div></div>`}
function integrationsScreen(){return `${head('Source integrations','Observe external requirements, record evaluations, and publish approved fact projections.',btn('Connection guide '+icon('arrow'),'connection-guide',''),'SOURCE PUBLICATION')}${current.concept==='guided'?journey(0,['Connect','Grant','Observe','Review'])+stepIntro('Keep discovery and execution separate','Select a source to inspect exactly what the integration is allowed to publish.'):''}<div class="card-grid">${sourceCard('servicenow','ServiceNow','Change and remediation requirements','2 external policies','6 min ago',true)}${sourceCard('github','GitHub','Reviewed changes and approval evidence','1 external policy','1 min ago',false)}</div><div class="two-col" style="margin-top:23px">${panel('Publication destinations',`<div class="definition-row" style="padding:17px 20px"><span>External policy observations</span><strong>Central policy store</strong></div><div class="definition-row" style="padding:17px 20px"><span>External evaluation receipts</span><strong>Central policy store</strong></div><div class="definition-row" style="padding:17px 20px"><span>Selected approval facts</span><strong>Scoped snapshot publication</strong></div><div class="inline-status">Integration cannot publish or activate executable policies.</div>`)}${panel('Recent observation',`<div class="panel-body"><div class="row spread"><span class="mono muted">RUN 01J / source-81</span>${badge('Partial coverage')}</div><p style="font-size:12px;margin:18px 0;color:var(--muted)">The schema and approval requirement were observed. One scripted condition remains opaque.</p>${btn('Read discovery report','contract','small','data-id="closure"')}</div>`)}</div>`}
function sourceCard(id,name,desc,count,age,warn){return `<article class="source-card"><div class="row"><div class="provider-logo ${id==='github'?'gh':''}">${id==='github'?'gh':'sn'}</div><div class="grow"><h2>${name}</h2><p class="muted" style="font-size:10px;margin-top:4px">${desc}</p></div>${badge(warn?'Review gap':'Current')}</div><dl><div><dt>CONTRACT KNOWLEDGE</dt><dd>${count}</dd></div><div><dt>LAST OBSERVATION</dt><dd>${observed&&warn?'Just now':age}</dd></div><div><dt>RUNNING ON</dt><dd class="mono">integration-01</dd></div><div><dt>PUBLICATION GRANT</dt><dd>Source scoped</dd></div></dl><div class="footer row spread"><span class="mock-label">Credentials remain with integration</span>${btn('Inspect '+icon('arrow'),'integration','small',`data-id="${id}"`)}</div></article>`}
function fleetScreen(){return `${head(current.concept==='atlas'?'Enforcement & integration nodes':'Registered endpoints','Assignments describe intent. Active revisions and last-seen times describe reported reality.',btn('Enrollment profile','enrollment',''))}${current.concept==='guided'?stepIntro('Inspect the endpoint before retrying','A received update is not proof of activation. Compare the desired and last reported active revision.'):''}<div class="stats">${stat('Registered','4','3 enforcement · 1 integration','fleet')}${stat('Connected',assigned?'4':'3','Authenticated current process bindings','check')}${stat('Policy drift',assigned?'0':'1','Desired and reported revisions differ','rollout')}${stat('Telemetry gaps',assigned?'0':'1','Missing required canary','observe')}</div>${panel('Endpoint registry',toolbar('Search endpoint IDs',['Enforcement','Integration'])+fleetTable())}<div class="callout" style="margin-top:20px"><strong>Managed endpoints have one activation authority.</strong>Central assignments govern policy activation. Direct policy writes are rejected for a managed scope; standalone operation is a separate mode.</div>`}
function traceTable(){return `<div class="table-wrap"><table><thead><tr><th>Operation</th><th>Service</th><th>Duration</th><th>Outcome</th><th>Received</th></tr></thead><tbody>${[['Evaluate change CHG-2041','ipe-server','4.2 ms','Denied','20 sec ago'],['Apply policy r17','ipe-server','18 ms','Applied','1 min ago'],['Observe closure constraints','ipe-integration','164 ms','Partial coverage','6 min ago'],['Publish external observation','ipe-control','12 ms','Complete','6 min ago']].map((r,i)=>`<tr><td><button class="record-link" data-action="trace" data-id="${i}">${r[0]}</button><span class="sub mono">trace-0${i+1} · permitted fields only</span></td><td class="mono">${r[1]}</td><td class="mono">${r[2]}</td><td>${badge(r[3])}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table></div>`}
function observabilityScreen(){return `${head('Observability','Execution, evidence, delivery, and telemetry compliance are separate operational signals.',btn('Telemetry profile','telemetry-profile',''))}${!assigned?`<div class="notice">${icon('warn')}<span><b>Canary missing on east-03.</b> The last observation is 12 minutes old; current runtime health is unknown.</span>${btn('Inspect','endpoint','small quiet','data-id="east-03"')}</div>`:''}<div class="stats">${stat('Evaluation p95','4.2 ms','Illustrative sample · last 60 minutes','observe')}${stat('Assignment lag',assigned?'0':'1 endpoint','Based on active-state reports','rollout')}${stat('External knowledge','1 stale','Source validity has elapsed','contracts')}${stat('Telemetry coverage',assigned?'4 / 4':'3 / 4','Required profile checks','check')}</div><div class="two-col"><div class="stack">${panel('Evaluation latency',`<div class="panel-body"><div class="row spread"><div><span class="metric-label">p95 · milliseconds</span><div class="metric-number">4.2 <small style="font-size:11px;font-weight:400;color:var(--muted)">ms</small></div></div>${badge('Stable','good')}</div>${spark(current.concept==='atlas'?'#72c4bd':'#779d86')}<div class="chart-axis"><span>08:45</span><span>09:00</span><span>09:15</span><span>09:45</span></div><div class="chart-caption">Illustrative telemetry, not measured IPE performance.</div></div>`)}${panel('Recent traces',traceTable(),'<span class="mono muted">LAST HOUR</span>')}</div><div class="stack">${panel('Independent health signals',health())}${panel('Required telemetry profile',`<div class="panel-body"><div class="health-row">Metrics scrape ${badge('Current')}</div><div class="health-row">Trace canary ${badge(assigned?'Current':'1 missing','warn')}</div><div class="health-row">Ingestion identity ${badge('Verified','good')}</div><div class="health-row">Sensitive fields ${badge('Redacted','good')}</div><div class="related-links">${btn('Inspect profile','telemetry-profile','small')}</div></div>`)}<div class="callout"><strong>Telemetry is not the audit record.</strong>Sampled traces explain behavior. Required decision audit uses a separate durable path.</div></div></div>`}
function journey(active,labels){return `<div class="journey">${labels.map((l,i)=>`<div class="${i===active?'current':''}"><b>${i+1}</b>${l}</div>`).join('')}</div>`}
function stepIntro(title,desc){return `<div class="step-intro"><span class="stepnum">1</span><div><strong>${title}</strong><small>${desc}</small></div></div>`}
function rolloutsScreen(){return `${head('Change approval guard · r17','Published policy and assigned revision stay separate from endpoint activation.',btn(assigned?'Review assignment':'Review assignment '+icon('arrow'),'assign','primary'),'ROLLOUT / PRODUCTION')}${journey(assigned?3:2,['Inspect policy','Validate','Assign','Confirm'])}<div class="two-col"><div class="stack">${panel('Assignment g42',`<div class="panel-body"><div class="row spread">${badge(assigned?'Applied':'Waiting for endpoint')}<span class="mono muted">POLICY approval / r17</span></div><div class="field-grid"><div><small>Requested by</small><p>Platform operator</p></div><div><small>Scope</small><p>Northstar · Production</p></div><div><small>Activation authority</small><p>Central assignment</p></div><div><small>Artifact integrity</small><p class="mono">sha256: 8c31…af90</p></div></div><div class="progress-track"><i style="width:${assigned?100:67}%"></i></div><span class="muted" style="font-size:10px">${assigned?3:2} of 3 endpoints have explicitly reported active r17.</span></div>`)}${panel('Reported endpoint state',fleetTable())}</div><div class="stack">${panel('Assignment safety checks',`<div class="panel-body"><div class="health-row">${icon('check')}Immutable policy revision pinned</div><div class="health-row">${icon('check')}Required schema compatible</div><div class="health-row">${icon('check')}Publisher is authorized</div><div class="health-row">${icon('check')}Direct endpoint writes disabled</div><div class="health-row">${icon(assigned?'check':'clock')}${assigned?'All endpoints confirmed':'Awaiting east-03 confirmation'}</div></div>`)}<div class="callout"><strong>A lost hint does not lose the assignment.</strong>Each endpoint periodically pulls current assignments. Delivery status becomes complete only after an active-state report.</div>${!assigned?btn('Simulate east-03 reconnect','reconnect','primary'):badge('All reports current')}</div></div>`}
function navItems(){return screens.map(([id,label,i])=>`<a href="${href(id)}" class="${current.screen===id?'active':''}" ${current.screen===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='rollouts'&&!assigned?'<span class="nav-count">1</span>':''}</a>`).join('')}
function reviewBar(){const c=concepts[current.concept],r=reviews[current.concept]||{};return `<div class="review-bar"><a class="back" href="#review">${icon('back')} <span>All concepts</span></a><span class="divider"></span><select id="concept-switch" aria-label="Switch UX concept">${Object.entries(concepts).map(([key,c])=>`<option value="${key}" ${key===current.concept?'selected':''}>${c.n} / ${c.title}</option>`).join('')}</select><span class="prototype-label">INTERACTIVE MOCK · ${c.tag.toUpperCase()}</span><span class="grow"></span>${btn(icon('star')+(r.selected?' Shortlisted':' Shortlist'),'shortlist',`small ${r.selected?'selected':''}`)}${btn(icon('note')+'<span class="note-label"> Add feedback</span>','feedback','small')}</div>`}
function appHeader(topnav=false){return `<header class="app-top">${topnav?brand():`<span class="breadcrumb">Northstar <span style="margin:0 8px">/</span> <b>${screens.find(s=>s[0]===current.screen)?.[1]}</b></span>`}${topnav?`<nav class="topnav" aria-label="Admin screens">${screens.map(([id,label])=>`<a href="${href(id)}" class="${current.screen===id?'active':''}" ${current.screen===id?'aria-current="page"':''}>${label==='External policies'?'External policies':label}</a>`).join('')}</nav>`:''}<div class="row" style="margin-left:auto"><span class="scope-chip"><i></i>Production</span><span class="avatar" title="Demo operator">JR</span></div></header>`}
function side(){return `<aside class="side">${brand()}<div class="space-picker"><span>Northstar workspace</span>${icon('down')}</div><div class="nav-label">${current.concept==='guided'?'YOUR WORKSPACE':'CONTROL PLANE'}</div><nav aria-label="Admin screens">${navItems()}</nav><div class="bottom"><p class="demo-note">DESIGN PROTOTYPE<br>All records are illustrative.<br>Actions change this demo only.</p><div class="row"><span class="avatar">JR</span><div>Policy operator<small style="display:block;font-size:9px;opacity:.6">Northstar · Production</small></div></div></div></aside>`}
function workspaceIndex(){return `<aside class="workspace-index"><h3>POLICY KNOWLEDGE</h3><a href="${href('policies')}" class="${current.screen==='policies'?'active':''}">Executable library <span style="float:right">6</span></a><a href="${href('contracts')}" class="${current.screen==='contracts'?'active':''}">External policies <span style="float:right">3</span></a><a href="${href('integrations')}" class="${current.screen==='integrations'?'active':''}">Source connections <span style="float:right">2</span></a><h3>OPERATIONS</h3><a href="${href('map')}" class="${current.screen==='map'?'active':''}">Service map</a><a href="${href('rollouts')}" class="${current.screen==='rollouts'?'active':''}">Assignments</a><a href="${href('fleet')}" class="${current.screen==='fleet'?'active':''}">Endpoint registry</a><a href="${href('observability')}" class="${current.screen==='observability'?'active':''}">Evidence & telemetry</a><p>Source authority, observation freshness, and local enforcement are separate dimensions.</p></aside>`}
function render(){const hash=location.hash.slice(1).split('/');if(!concepts[hash[0]]){history.replaceState(null,'','#workspace/overview');render();return}current={concept:hash[0],screen:screens.some(s=>s[0]===hash[1])?hash[1]:'overview'};if(current.concept==='workspace'){renderBoldWorkspace();return}const content=current.screen==='overview'?({console:overviewConsole,workspace:workspaceOverview,atlas:atlasOverview,guided:guidedOverview}[current.concept])():({policies:policiesScreen,contracts:contractsScreen,integrations:integrationsScreen,fleet:fleetScreen,observability:observabilityScreen,rollouts:rolloutsScreen,map:workspaceMap}[current.screen])();const top=['workspace','atlas'].includes(current.concept);$('#app').innerHTML=`<div class="review-shell ${concepts[current.concept].class}">${reviewBar()}${current.concept==='workspace'?paletteStrip():''}<div class="app-shell">${top?'':side()}<main class="main">${appHeader(top)}<div class="main-inner">${current.concept==='workspace'?`<div class="workspace-layout">${workspaceIndex()}<div>${content}${foot()}</div></div>`:content+foot()}</div></main></div></div>`;applyPalette();document.title=`${concepts[current.concept].title} · ${screens.find(s=>s[0]===current.screen)[1]} · IPE Design Review`}
function renderGallery(){const count=Object.values(reviews).filter(r=>r.selected).length;$('#app').innerHTML=`<main class="review-home"><header class="review-header">${brand()}<span class="meta">ADMIN EXPERIENCE / DESIGN EXPLORATION 01</span>${btn(icon('download')+' Export feedback','export','small')}</header><section class="review-hero"><div><div class="kicker" style="color:#778579">FOUR DIRECTIONS. ONE CONTROL PLANE.</div><h1>How should<br>running IPE feel?</h1><p>Policy Workspace is the selected direction. Explore the operational workspace, enforcement scopes, integrations, and telemetry, or revisit the other concepts below.</p><p style="margin-top:20px"><a class="btn primary" href="#workspace/overview">Open operational workspace →</a> <a class="btn" href="#workspace/map">Open service map →</a></p></div><aside><div class="kicker" style="color:#7b897f">A WORKING DESIGN REVIEW</div><div class="row"><span class="stepnum">1</span><p>Open a concept. Eight connected screens show the same production scenario.</p></div><div class="row"><span class="stepnum">2</span><p>Inspect a policy, review an external constraint, or simulate an endpoint catching up.</p></div><div class="row"><span class="stepnum">3</span><p>Shortlist a direction and capture what to keep or change. Feedback stays in this browser.</p></div></aside></section><section class="concept-grid" aria-label="Four UX directions">${Object.entries(concepts).map(([key,c])=>`<article class="concept-card"><a class="concept-cover" href="#${key}/overview" aria-label="Explore ${c.title}"><img src="previews/${key}.png" alt="${c.title} admin overview preview" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><span class="cover-placeholder">${c.title}</span></a><div class="concept-card-body"><div class="concept-name"><span class="number">${c.n}</span><h2>${c.title}</h2></div><p>${c.description}</p><div class="concept-fit">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="row spread"><a class="btn primary" href="#${key}/overview">Explore concept ${icon('arrow')}</a>${btn(icon('star')+(reviews[key]?.selected?' Shortlisted':' Shortlist'),'shortlist',reviews[key]?.selected?'selected':'',`data-concept="${key}"`)}</div></div></article>`).join('')}</section><section class="review-section"><div class="kicker" style="color:#7b897f">CHOOSE THE ORGANIZING IDEA</div><h2>Different priorities. Clear tradeoffs.</h2><div class="compare"><table><thead><tr><th></th>${Object.values(concepts).map(c=>`<th>${c.n} / ${c.short}</th>`).join('')}</tr></thead><tbody><tr><td>Starts with</td><td>Health and exceptions</td><td>Policy meaning and source context</td><td>Connected services and impact</td><td>The next task to complete</td></tr><tr><td>Best for</td>${Object.values(concepts).map(c=>`<td>${c.best}</td>`).join('')}</tr><tr><td>Tradeoff</td>${Object.values(concepts).map(c=>`<td>${c.tradeoff}</td>`).join('')}</tr><tr><td>Related screens</td><td colspan="4">Overview · executable policies · external policies & evaluations · integrations · endpoint registry · observability · rollout</td></tr></tbody></table></div><div class="review-bottom"><div><strong>${count?`${count} direction${count===1?'':'s'} shortlisted`:'Make a selection, or borrow from several.'}</strong><p>Each concept has a feedback form. Export your notes to carry the review into the next iteration.</p></div>${btn(icon('download')+' Export review notes','export','')}</div></section><footer class="review-section row spread" style="font-size:11px;color:#8b948d"><span>IPE ADMIN · CONCEPT REVIEW</span><span>Sample data. Simulated actions. No live changes.</span></footer></main>`;document.title='IPE Admin · Four UX Directions'}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(title,subtitle,body,footer='',drawer=false){dialogOpener=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop ${drawer?'drawer-backdrop':''}" data-backdrop="true"><section class="dialog ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><header class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';$('#overlay .close').focus()}
function close(){const old=dialogOpener;$('#overlay').innerHTML='';document.body.style.overflow='';if(old?.isConnected)old.focus()}
let openRecord=null;
function openPolicy(id){selectedRecord=id;openRecord={kind:'policy',id};const p=policies.find(p=>p.id===id)||policies[0];modal(p.name,`${p.rev} · Executable policy · ${p.owner}`,policyDetails(p),btn('Close','close')+(p.id==='approval'?btn('Review assignment '+icon('arrow'),'assign','primary'):''),true)}
function openContractLegacy(id){const c=contractRows.find(c=>c.id===id)||contractRows[0];openRecord={kind:'contract',id:c.id};modal(c.name,`${c.source} · External policy observation`,`${badge(c.state)} <span class="mono muted" style="margin-left:10px">${c.version}</span><div class="field-grid"><div><small>Enforcement authority</small><p>${c.source}, not IPE</p></div><div><small>Publication authority</small><p>Source-scoped integration</p></div><div><small>Last observed</small><p>${observed&&c.id==='closure'?'Just now':c.age}</p></div><div><small>Knowledge state</small><p>${c.state==='Stale'?'Observation validity elapsed':'Observation is valid; coverage is separate'}</p></div></div><div class="rule"><small>DISCOVERED REQUIREMENT</small><p>${c.summary}</p></div>${c.id==='closure'?`<div class="notice">${icon('warn')}<span><b>One condition remains opaque.</b><br>Custom source script cannot be interpreted by this adapter.</span></div>`:''}<div class="definition-row"><span>Discovery identity</span><strong>Integration reader</strong></div><div class="definition-row"><span>Intended actor</span><strong>Change operator</strong></div><div class="definition-row"><span>Mapping</span><strong class="mono">policy-map / v3</strong></div><div class="callout"><strong>Refresh knowledge, not executable policy.</strong>A new observation can update validity and provenance. It does not erase unknown conditions or activate a local rule.</div><div class="related-links">${btn('Inspect external evaluation','receipt','small')}${btn('Draft a separate local guard','translate','small',`data-id="${c.id}"`)}</div>`,btn(icon('refresh')+' Re-observe source','observe-source','primary')+btn('Close','close'),true)}
function openEndpoint(id){const e=endpoints.find(e=>e.id===id)||endpoints[2];const repaired=e.id==='east-03'&&assigned;modal(e.id,`${e.kind} endpoint · ${e.site} · Managed mode`,`${badge(repaired?'Connected':e.state)}<div class="field-grid"><div><small>Desired central revision</small><p class="mono">${e.desired}</p></div><div><small>Reported active revision</small><p class="mono">${repaired?'r17':e.active}</p></div><div><small>Local catalog revision</small><p class="mono">${repaired?'8':e.local}</p></div><div><small>Assignment generation</small><p class="mono">${e.kind==='Enforcement'?'g42':'g19'}</p></div><div><small>Authenticated incarnation</small><p class="mono">instance-${e.id}-04</p></div><div><small>Last report</small><p>${e.id==='east-03'&&!assigned?'12 minutes ago':'18 seconds ago'}</p></div></div><div class="detail-section"><h3>Independent health signals</h3><div class="health-row">Connection ${badge(repaired?'Connected':e.state)}</div><div class="health-row">Applied assignment ${badge(e.id==='east-03'&&!assigned?'Waiting':'Applied')}</div><div class="health-row">Telemetry ${badge(repaired?'Compliant':e.telemetry)}</div><div class="health-row">Evidence ${badge(e.id==='east-03'?'Last known expired':'Current',e.id==='east-03'?'warn':'good')}</div></div><div class="callout"><strong>Local revision ${e.local} is not a fleet-wide revision.</strong>Report the central policy revision, assignment generation, endpoint incarnation, and local revision together.</div>`,(e.id==='east-03'&&!assigned?btn('Simulate reconnection','reconnect','primary'):'')+btn('Close','close'),true)}
function openIntegration(id){const sn=id!=='github';modal(sn?'ServiceNow connection':'GitHub connection','Source-scoped integration · running on integration-01',`<div class="row">${badge('Connected')} ${badge(sn?'Partial coverage':'Current')}</div><div class="field-grid"><div><small>Connection reference</small><p class="mono">${sn?'conn-servicenow-01':'conn-github-01'}</p></div><div><small>Credential handling</small><p>Held by integration runtime</p></div><div><small>Read capability</small><p>${sn?'Metadata and permitted constraints':'Branch rules and approval evidence'}</p></div><div><small>Publication scope</small><p>Northstar / Production</p></div></div><div class="detail-section"><h3>Granted publication paths</h3><div class="health-row">${icon('check')}External policy observations</div><div class="health-row">${icon('check')}Contextual external evaluation receipts</div><div class="health-row">${icon('check')}Approved fact projections</div><div class="health-row">${icon('close')}Executable policy activation — not granted</div></div><div class="callout"><strong>Connection health is not complete knowledge.</strong>A successful connection can still return partial metadata, denied resources, or unmodeled requirements.</div>`,btn('Observe source','observe-source','primary')+btn('Close','close'),true)}
function receipt(id){const ok=id==='accepted';modal('External evaluation observation','Immutable contextual receipt · illustrative data',`${badge(ok?'Accepted by source':'Denied',ok?'good':'bad')}<div class="field-grid"><div><small>Subject</small><p>${ok?'CHG-2038':'CHG-2041'}</p></div><div><small>Requested operation</small><p>Validate change closure</p></div><div><small>External enforcer</small><p>ServiceNow</p></div><div><small>Intended actor</small><p>Change operator</p></div><div><small>Observed at</small><p>09:37 UTC · sample time</p></div><div><small>Input binding</small><p class="mono">input-digest / ${ok?'7b03':'4f20'}</p></div></div><div class="rule"><small>REPORTED RESULT</small><p>${ok?'The source accepted validation for the recorded input.':'The source rejected closure because required approval evidence was incomplete.'}</p></div><div class="callout"><strong>This receipt is not a reusable permission.</strong>The result belongs to this actor, operation, input, and time. Future execution can reach a different outcome.</div>`,btn('Close','close'),true)}
function assign(){modal('Review an assignment','Simulation only · publish and activation remain separate',`<div class="row spread"><strong>Change approval guard</strong><span class="mono">r17 · sha256:8c31…af90</span></div><div class="field-grid"><div><small>Assignment scope</small><p>Northstar / Production</p></div><div><small>Authority</small><p>Policy operator · rollout grant</p></div></div><div class="form-label">Production scope · all three enforcement endpoints</div>${endpoints.filter(e=>e.kind==='Enforcement').map(e=>`<label class="choice"><input type="checkbox" checked disabled name="target" value="${e.id}"><span><strong>${e.id}</strong><small>Managed scope · direct policy writes rejected</small></span>${badge(e.id==='east-03'&&!assigned?'Waiting':'Current')}</label>`).join('')}<div class="notice neutral"><span>A committed assignment sends a best-effort hint. Completion still requires active-state reports.</span></div>`,btn('Cancel','close')+btn('Simulate assignment','commit-assignment','primary'))}
function feedback(){const key=current.concept;if(!key)return;const c=concepts[key],r=reviews[key]||{};modal(`Review ${c.title}`,'Notes and shortlist are saved in this browser. Export them to share.',`<div class="review-detail">${c.best}<br><span style="color:#87917b">Tradeoff: ${c.tradeoff}</span></div><label class="form-label" for="keep">What should we keep?</label><textarea id="keep" class="form-input" placeholder="Navigation, information hierarchy, interactions…">${esc(r.keep||'')}</textarea><label class="form-label" for="change">What should we refine?</label><textarea id="change" class="form-input" placeholder="What feels unclear, missing, or too dense?">${esc(r.change||'')}</textarea><label class="choice"><input id="shortlist-check" type="checkbox" ${r.selected?'checked':''}><span><strong>Shortlist this direction</strong><small>You can shortlist more than one concept.</small></span></label>`,btn('Cancel','close')+btn('Save feedback','save-feedback','primary'))}
function trace(id){const names=['Evaluate change CHG-2041','Apply policy r17','Observe closure constraints','Publish external observation'];modal(names[Number(id)||0],'Permitted trace projection · sample trace',`${badge(Number(id)===0?'Denied':Number(id)===2?'Partial coverage':'Complete')}<div class="field-grid"><div><small>Service</small><p>${Number(id)===2?'ipe-integration':Number(id)===3?'ipe-control':'ipe-server'}</p></div><div><small>Correlation</small><p class="mono">trace-0${Number(id)+1} / change-2041</p></div></div><div class="trace-waterfall">${([ [['Authorize request',0,23,'0.4 ms'],['Capture local snapshot',15,35,'0.7 ms'],['Evaluate policy sections',30,85,'2.8 ms'],['Project permitted result',85,15,'0.3 ms']], [['Fetch current assignment',0,40,'6 ms'],['Verify policy revision',20,20,'3 ms'],['Activate local revision',30,40,'6 ms'],['Report active state',60,20,'3 ms']], [['Authorize source scope',0,10,'4 ms'],['Read source constraints',5,85,'140 ms'],['Map supported fields',65,15,'12 ms'],['Record coverage gap',75,10,'8 ms']], [['Authorize publication',0,20,'2 ms'],['Validate typed record',15,35,'4 ms'],['Store observation',35,35,'4 ms'],['Append audit receipt',65,20,'2 ms']] ][Number(id)||0]).map(([n,l,w,t])=>`<div class="span-line"><span>${n}</span><div><i style="margin-left:${l/2}%;width:${w/1.7}%"></i></div><small>${t}</small></div>`).join('')}</div><div class="callout"><strong>Visibility follows disclosure grants.</strong>Raw inputs, provider credentials, and protected source topology are absent. This sampled diagnostic is separate from durable audit.</div>`,btn('Close','close'),true)}
function action(name,el){const id=el?.dataset.id;switch(name){case 'close':close();break;case 'shortlist':{const key=el.dataset.concept||current.concept;reviews[key]={...reviews[key],selected:!reviews[key]?.selected};persist();render();toast(reviews[key].selected?`${concepts[key].title} shortlisted.`:'Removed from shortlist.');break}case 'feedback':feedback();break;case 'save-feedback':reviews[current.concept]={...reviews[current.concept],keep:$('#keep').value,change:$('#change').value,selected:$('#shortlist-check').checked};persist();close();render();toast('Feedback saved in this browser.');break;case 'export':{const data={review:'IPE admin UX directions',dataType:'Browser-local design feedback',concepts:Object.entries(concepts).map(([key,c])=>({id:key,title:c.title,...reviews[key]}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ipe-admin-ux-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Review notes exported.');break}case 'policy':detailTab='definition';openPolicy(id);break;case 'contract':openContract(id);break;case 'endpoint':openEndpoint(id);break;case 'integration':openIntegration(id);break;case 'catalog':modal('One catalog, three record families','Typed resources with separate publication permissions',`<div class="task-card"><div>${badge('Executable','blue')}<h3 style="margin-top:10px">Executable policy revisions</h3><p>Published by authorized policy authors. Assigned to local enforcement.</p></div></div><div class="task-card"><div>${badge('External policy','purple')}<h3 style="margin-top:10px">Observed external requirements</h3><p>Published by integration. Remain enforced by the external source.</p></div></div><div class="task-card"><div>${badge('Observation','purple')}<h3 style="margin-top:10px">External evaluation receipts</h3><p>Results bound to actor, input, operation, and time.</p></div></div>`,btn('Inspect policy library','go-policies','primary'));break;case 'go-policies':close();location.hash=href('policies');break;case 'receipt':receipt(id);break;case 'select-record':selectedRecord=id;detailTab='definition';render();break;case 'detailtab':detailTab=el.dataset.tab;if($('#overlay .dialog'))openPolicy(selectedRecord);else render();break;case 'test':{const result=scenario==='valid'?['Allow','The sample contains two distinct maintainers and fresh evidence.']:scenario==='single'?['Denied','The sample contains only one distinct maintainer.']:['Indeterminate','The evidence has expired; this must not become an allow.'];$('#test-result').innerHTML=`<div class="notice ${scenario==='valid'?'safe':''}"><span>${badge(result[0])} <span style="margin-left:8px">${result[1]}</span></span></div>`;break}case 'new-policy':modal('Create an executable draft','A draft is not an assignment and does not activate a rule.',`<label class="form-label" for="draft-name">Policy name</label><input id="draft-name" class="form-input" placeholder="e.g. Production release guard"><label class="form-label" for="draft-purpose">What should this policy require?</label><textarea id="draft-purpose" class="form-input" placeholder="Describe the intended local enforcement rule."></textarea>`,btn('Cancel','close')+btn('Create demo draft','create-policy','primary'));break;case 'create-policy':{const name=$('#draft-name').value.trim();if(!name){$('#draft-name').focus();toast('Enter a policy name.');break}policies.unshift({id:'draft-'+Date.now(),name,rev:'r1',origin:'Authored',status:'Draft',scope:'Production changes',coverage:'Not assigned',rule:esc($('#draft-purpose').value.trim()||'Define the intended requirement before testing.'),owner:'Platform team'});close();location.hash=href('policies');render();toast('Executable draft created. No assignment or activation occurred.');break}case 'translate':modal('Draft a separate local guard','Explicit translation · executable authoring authority required',`<div class="notice neutral"><span>This creates a new draft referencing the external observation. It does not convert the source policy into an active policy.</span></div><label class="form-label" for="translation-name">Draft name</label><input class="form-input" id="translation-name" value="Local change closure guard"><label class="form-label" for="dependence">Source dependence</label><select class="form-input" id="dependence"><option>Depends on source observation validity</option><option>Independent local requirement</option></select><div class="callout">The scripted external condition remains unknown. A local guard cannot claim to reproduce the entire external decision.</div>`,btn('Cancel','close')+btn('Create translated draft','create-translation','primary'));break;case 'create-translation':{const name=$('#translation-name').value.trim();if(!name){toast('Enter a name for the separate draft.');break}policies.unshift({id:'translated-'+Date.now(),name,sourceDependence:$('#dependence').value,rev:'r1',origin:'Translated',status:'Draft',scope:'Change closure',coverage:'Not assigned',rule:'Require <em>supported approval evidence</em>; preserve the unmodeled external condition as a gap.',owner:'Policy operator'});close();location.hash=href('policies');render();toast('Separate translated draft created. External policy and active rules are unchanged.');break}case 'observe-source':observed=true;if(openRecord?.kind==='contract'&&$('#overlay .dialog'))openContract(openRecord.id);else{close();render()}toast('New source observation recorded. Coverage remains partial; executable policies unchanged.');break;case 'assign':assign();break;case 'commit-assignment':{const selected=[...document.querySelectorAll('input[name="target"]:checked')].map(x=>x.value);if(!selected.length){toast('Select at least one target endpoint.');break}close();location.hash=href('rollouts');render();toast(`Assignment recorded for ${selected.length} target${selected.length===1?'':'s'}. Activation still requires endpoint reports.`);break}case 'reconnect':assigned=true;close();render();toast('Simulated east-03 report: central r17 → local revision 8. Assignment is now confirmed.');break;case 'trace':trace(id);break;case 'telemetry-profile':modal('Production telemetry profile','Admission and rollout checks · no synchronous evaluation dependency',`<div class="definition-row"><span>Required metrics</span><strong>Scrape received within 60 seconds</strong></div><div class="definition-row"><span>Diagnostic trace</span><strong>Canary received within 5 minutes</strong></div><div class="definition-row"><span>Identity binding</span><strong>Authenticated endpoint and scope</strong></div><div class="definition-row"><span>Failure consequence</span><strong>Block new rollout; raise an incident</strong></div><div class="callout"><strong>Sampling is not a health guarantee.</strong>Use a diagnostic canary and ingestion signals rather than assuming a lack of application traces means the service is down. These intervals are illustrative.</div>`,btn('Close','close'));break;case 'enrollment':modal('Endpoint enrollment profile','A registry ID is not authentication',`<div class="definition-row"><span>Identity</span><strong>Operator-approved workload binding</strong></div><div class="definition-row"><span>Permitted roles</span><strong>Enforcement or integration</strong></div><div class="definition-row"><span>Scope</span><strong>Explicit tenant and environment</strong></div><div class="definition-row"><span>Process incarnation</span><strong>Bound by enrollment authority</strong></div><div class="callout">A self-reported incarnation cannot replace another process. Addresses and labels are mutable metadata, not publication authority.</div>`,btn('Close','close'));break;case 'connection-guide':modal('Connecting a source','Conceptual setup · no real credentials are accepted',`<div class="task-card"><div><h3>1. Enroll the integration endpoint</h3><p>Bind authenticated identity and the permitted production scope.</p></div></div><div class="task-card"><div><h3>2. Configure provider access at the runtime</h3><p>Provider secrets stay with the integration service.</p></div></div><div class="task-card"><div><h3>3. Grant scoped publication</h3><p>Allow selected external policy observations, evaluation receipts, and fact projections.</p></div></div><div class="task-card"><div><h3>4. Observe and review coverage</h3><p>Connectivity alone cannot prove complete source knowledge.</p></div></div>`,btn('Close','close'));break;case 'reset':externalRefreshes={};externalTab='requirements';policies=structuredClone(initialPolicies);observed=false;assigned=false;query='';filter='';scenario='valid';selectedRecord='approval';close();render();toast('Demo data reset. Your design feedback is preserved.');break}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el);else if(e.target.dataset.backdrop)close()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [role="button"]')){e.preventDefault();action(e.target.dataset.action,e.target)}if(e.key==='Escape')close();if(e.key==='Tab'&&$('#overlay .dialog')){const f=[...document.querySelectorAll('#overlay button,#overlay a,#overlay input,#overlay textarea,#overlay select')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
document.addEventListener('change',e=>{if(e.target.id==='concept-switch'){location.hash=`#${e.target.value}/${current.screen}`;query='';filter=''}if(e.target.id==='record-filter'){filter=e.target.value;render()}if(e.target.id==='scenario')scenario=e.target.value});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){const pos=e.target.selectionStart;query=e.target.value;render();const input=$('#record-search');input.focus();input.setSelectionRange(pos,pos)}});
window.addEventListener('hashchange',()=>{close();query='';filter='';render();window.scrollTo(0,0)});
render();

function workspaceMap(){return `${head('Service map','Inspect registered services, source connections, and policy delivery across production.',link('Open endpoint registry','fleet'),'ADMIN / PRODUCTION')}${panel('Policy delivery & source knowledge',topology())}<div class="card-grid" style="margin-top:20px">${panel('Integration runtime',`<div class="panel-body"><div class="row spread"><strong>integration-01</strong>${badge('Connected')}</div><p class="muted" style="margin:12px 0;font-size:12px">Observes ServiceNow and GitHub, publishes external policies, and serves expiring facts. Source links above are mediated by this runtime.</p>${btn('Inspect integration endpoint','endpoint','small','data-id="integration-01"')}</div>`)}${panel('Independent health signals',health())}</div><div class="callout" style="margin-top:20px"><strong>Read this map as service relationships.</strong>Select a source to inspect its publication grants, the policy service to inspect record ownership, or an endpoint to inspect desired and active revisions. Fact delivery and telemetry transport are separate paths; the map focuses on policy delivery and external knowledge.</div>`}
